/* Sentinel Design System v1.3.1 — theme
 * Auto-generated by scripts/export-llms.js from app/globals.css — do not edit by hand.
 *
 * Requires Tailwind CSS v4. Import after Tailwind:
 *   @import "tailwindcss";
 *   @import "./theme.css";
 * Light: :root or [data-snt-theme="light"]. Dark: .dark or [data-snt-theme="dark"].
 */

@custom-variant dark (&:is(.dark *));

/* ===================================================================
   Sentinel DESIGN SYSTEM — COLOR TOKENS
   Light values: :root and [data-snt-theme="light"]
   Dark values:  .dark and [data-snt-theme="dark"]
   =================================================================== */

:root,
[data-snt-theme="light"] {
  /* Severity — static, same in both modes */
  --snt-severity-info: #7dafd6;
  --snt-severity-low: #63a100;
  --snt-severity-medium: #f5bf40;
  --snt-severity-high: #d13d2e;
  --snt-severity-critical: #772ed1;

  /* Brand / Primary — indigo (Tailwind indigo 600/700, 500 darkened for 5.4:1 text) */
  --snt-brand-primary-50:  #eef0ff;
  --snt-brand-primary-100: #e0e3ff;
  --snt-brand-primary-200: #c7ccfe;
  --snt-brand-primary-500: #5b5bd6;
  --snt-brand-primary-600: #4f46e5;
  --snt-brand-primary-700: #4338ca;
  --snt-brand-primary-800: #312e81;

  /* Brand / Secondary — base hsl(14, 81%, 64%) */
  --snt-brand-secondary-50:  #fef4f1;
  --snt-brand-secondary-100: #fadad1;
  --snt-brand-secondary-200: #f5b6a3;
  --snt-brand-secondary-500: #ee7b59;
  --snt-brand-secondary-600: #e85326;
  --snt-brand-secondary-700: #c23d14;
  --snt-brand-secondary-800: #81290e;

  /* Scale / Blue — base hsl(206, 52%, 66%) */
  --snt-scale-blue-50:  #f7fafd;
  --snt-scale-blue-100: #e8f1f8;
  --snt-scale-blue-200: #c9deee;
  --snt-scale-blue-500: #7dafd6;
  --snt-scale-blue-600: #2f6893;
  --snt-scale-blue-700: #234f70;
  --snt-scale-blue-800: #18374e;

  /* Scale / Green — base hsl(83, 100%, 32%) */
  --snt-scale-green-50:  #f1ffdb;
  --snt-scale-green-100: #e8ffc2;
  --snt-scale-green-200: #a5ff14;
  --snt-scale-green-500: #63a100;
  --snt-scale-green-600: #3f6600;
  --snt-scale-green-700: #294200;
  --snt-scale-green-800: #192900;

  /* Scale / Yellow — base hsl(42, 90%, 61%) */
  --snt-scale-yellow-50:  #fefaf0;
  --snt-scale-yellow-100: #fcebc5;
  --snt-scale-yellow-200: #f8d072;
  --snt-scale-yellow-500: #f5bf40;
  --snt-scale-yellow-600: #da9c0b;
  --snt-scale-yellow-700: #795706;
  --snt-scale-yellow-800: #443104;

  /* Scale / Red — base hsl(6, 64%, 50%) */
  --snt-scale-red-50:  #fcf3f2;
  --snt-scale-red-100: #f4d1cd;
  --snt-scale-red-200: #ebaaa3;
  --snt-scale-red-500: #d13d2e;
  --snt-scale-red-600: #8e2a1f;
  --snt-scale-red-700: #712219;
  --snt-scale-red-800: #471510;

  /* Scale / Purple — base hsl(267, 64%, 50%) */
  --snt-scale-purple-50:  #f7f2fc;
  --snt-scale-purple-100: #dcc9f3;
  --snt-scale-purple-200: #ab7de3;
  --snt-scale-purple-500: #772ed1;
  --snt-scale-purple-600: #5d24a3;
  --snt-scale-purple-700: #4f1e8a;
  --snt-scale-purple-800: #301254;

  /* Neutral / Grey — zinc; 400 tuned to 3.2:1 so it can bound inputs */
  --snt-neutral-grey-00:  #ffffff;
  --snt-neutral-grey-50:  #fafafa;
  --snt-neutral-grey-100: #f4f4f5;
  --snt-neutral-grey-200: #e4e4e7;
  --snt-neutral-grey-300: #d4d4d8;
  --snt-neutral-grey-400: #8f8f98;
  --snt-neutral-grey-500: #71717a;
  --snt-neutral-grey-600: #52525b;
  --snt-neutral-grey-700: #3f3f46;
  --snt-neutral-grey-800: #27272a;
  --snt-neutral-grey-900: #18181b;

  /* Neutral / Divider */
  --snt-neutral-divider-10: rgba(9, 9, 11, 0.08);
  --snt-neutral-divider-20: rgba(9, 9, 11, 0.14);

  /* Surface */
  --snt-surface-app: #ffffff;
  --snt-surface-page: #fafafa;
  --snt-surface-row: #ffffff;
  --snt-surface-row-hover: #f4f4f5;
  --snt-surface-row-visited: #fafafa;
  --snt-surface-table-header: #f4f4f5;

  /* Feedback */
  --snt-feedback-info: #7dafd6;
  --snt-feedback-success: #63a100;
  --snt-feedback-warning: #e6a200;
  --snt-feedback-alert: #ae2700;

  /* Data */
  --snt-data-1: #9acbe5;
  --snt-data-2: #ffaf97;
  --snt-data-3: #c4def3;
  --snt-data-4: #a7adb2;
  --snt-data-5: #0f69aa;
  --snt-data-6: #c1674d;
  --snt-data-7: #1f5077;
  --snt-data-8: #394751;
  --snt-data-9: #cde5f2;
  --snt-data-10: #ffd9ce;

  /* Status */
  --snt-status-ongoing: #7dafd6;
  --snt-status-finished: #63a100;
  --snt-status-not-accessible: #e6a200;
  --snt-status-incomplete: #e6a200;
  --snt-status-delayed: #e6a200;
  --snt-status-cancelled: #ae2700;
  --snt-status-timeout: #ae2700;
  --snt-status-error: #ae2700;
  --snt-status-inaccessible: #ae2700;
  --snt-status-too-many-inaccessible: #ae2700;

  /* Text — structural roles */
  --snt-text-primary:     #09090b;
  --snt-text-secondary:   #52525b;
  --snt-text-disabled:    #a1a1aa;
  --snt-text-placeholder: #71717a;
  --snt-text-white:       #ffffff;
  --snt-text-inverse:     #ffffff;
  --snt-text-on-accent:   #ffffff;

  /* Text — semantic colored text. Tuned for WCAG AA+ on each mode's primary surface. */
  --snt-text-link:    #4f46e5;                         /* indigo 600 — 6.29:1 vs white, AA */
  --snt-text-brand:   var(--snt-brand-primary-600);    /* = indigo 600 — 6.29:1, AA */
  --snt-text-success: #2f7d2c;                         /* deep readable green — 5.13:1, AA */
  --snt-text-warning: #8e6800;                         /* amber — 5.08:1, AA, looks yellow not brown */
  --snt-text-error:   #b0291e;                         /* deep red — 6.60:1, AA */
  --snt-text-info:    var(--snt-scale-blue-600);       /* = #2F6893 light — 5.96:1, AA */

  /* Shadow — light-mode elevation */
  --snt-shadow-xs:  0 1px 2px 0 rgba(0, 0, 0, 0.04);
  --snt-shadow-sm:  0 1px 3px 0 rgba(0, 0, 0, 0.06), 0 1px 2px 0 rgba(0, 0, 0, 0.04);
  --snt-shadow-md:  0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -1px rgba(0, 0, 0, 0.04);
  --snt-shadow-lg:  0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -2px rgba(0, 0, 0, 0.04);
  --snt-shadow-xl:  0 20px 25px -5px rgba(0, 0, 0, 0.10), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
  --snt-shadow-2xl: 0 25px 50px -12px rgba(0, 0, 0, 0.18);

  /* shadcn compatibility layer */
  --background: #ffffff;
  --foreground: #09090b;
  --card: #ffffff;
  --card-foreground: #09090b;
  --popover: #ffffff;
  --popover-foreground: #09090b;
  --primary: #4f46e5;
  --primary-foreground: #ffffff;
  --secondary: #f4f4f5;
  --secondary-foreground: #18181b;
  --muted: #f4f4f5;
  --muted-foreground: #52525b;
  --accent: #f4f4f5;
  --accent-foreground: #18181b;
  --destructive: #d13d2e;
  --border: rgba(9, 9, 11, 0.08);
  --input: rgba(9, 9, 11, 0.14);
  --ring: #5b5bd6;
  --radius: 0.375rem;
  --chart-1: #9acbe5;
  --chart-2: #ffaf97;
  --chart-3: #c4def3;
  --chart-4: #a7adb2;
  --chart-5: #0f69aa;

  /* Button color tokens — static, light-mode values in both themes */
  --snt-btn-neutral-100: #f4f4f5;
  --snt-btn-neutral-300: #d4d4d8;
  --snt-btn-neutral-600: #52525b;
  --snt-btn-neutral-700: #3f3f46;
  --snt-btn-neutral-800: #18181b;
  --snt-btn-primary-50:  #eef0ff;
  --snt-btn-primary-600: #4f46e5;
  --snt-btn-primary-700: #4338ca;
  --snt-btn-success-50:  #eff7e5;
  --snt-btn-success-600: #406800;
  --snt-btn-success-700: #284000;
  --snt-btn-warning-50:  #fffbf0;
  --snt-btn-warning-600: #e6a200;
  --snt-btn-warning-700: #805a00;
  --snt-btn-error-50:    #fff0ef;
  --snt-btn-error-600:   #ae2700;
  --snt-btn-error-700:   #881f00;

  /* Sidebar — always dark, not affected by theme toggle */
  --sidebar: #0f1010;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #1383d4;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: rgba(255, 255, 255, 0.06);
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgba(255, 255, 255, 0.08);
  --sidebar-ring: #1383d4;

  /* Z-index — 7 fixed layers. Never invent ad-hoc values like z-[99]. */
  --snt-z-base:      0;
  --snt-z-sticky:    10;
  --snt-z-dropdown:  20;
  --snt-z-overlay:   30;
  --snt-z-sidebar:   40;
  --snt-z-modal:     50;
  --snt-z-toast:     60;

  /* Motion — semantic durations + easings. */
  --snt-motion-duration-instant:    75ms;
  --snt-motion-duration-snap:      100ms;
  --snt-motion-duration-default:   150ms;
  --snt-motion-duration-emphasis:  200ms;
  --snt-motion-duration-spatial:   300ms;

  --snt-motion-ease-linear:   linear;
  --snt-motion-ease-in:       cubic-bezier(0.4, 0, 1, 1);
  --snt-motion-ease-out:      cubic-bezier(0, 0, 0.2, 1);
  --snt-motion-ease-in-out:   cubic-bezier(0.4, 0, 0.2, 1);
}

.dark,
[data-snt-theme="dark"] {
  /* Brand / Primary — indigo, flipped */
  --snt-brand-primary-50:  #1b1a3f;
  --snt-brand-primary-100: #25236a;
  --snt-brand-primary-200: #3730a3;
  --snt-brand-primary-500: #818cf8;
  --snt-brand-primary-600: #a5b4fc;
  --snt-brand-primary-700: #c7d2fe;
  --snt-brand-primary-800: #e0e7ff;

  /* Brand / Secondary — flipped, base hsl(14, 81%, 64%) */
  --snt-brand-secondary-50:  #81290e;
  --snt-brand-secondary-100: #c23d14;
  --snt-brand-secondary-200: #e85326;
  --snt-brand-secondary-500: #ee7b59;
  --snt-brand-secondary-600: #f5b6a3;
  --snt-brand-secondary-700: #fadad1;
  --snt-brand-secondary-800: #fef4f1;

  /* Scale / Blue — flipped, base hsl(206, 52%, 66%) */
  --snt-scale-blue-50:  #18374e;
  --snt-scale-blue-100: #234f70;
  --snt-scale-blue-200: #2f6893;
  --snt-scale-blue-500: #7dafd6;
  --snt-scale-blue-600: #c9deee;
  --snt-scale-blue-700: #e8f1f8;
  --snt-scale-blue-800: #f7fafd;

  /* Scale / Green — flipped, base hsl(83, 100%, 32%) */
  --snt-scale-green-50:  #192900;
  --snt-scale-green-100: #294200;
  --snt-scale-green-200: #3f6600;
  --snt-scale-green-500: #63a100;
  --snt-scale-green-600: #a5ff14;
  --snt-scale-green-700: #e8ffc2;
  --snt-scale-green-800: #f1ffdb;

  /* Scale / Yellow — flipped, base hsl(42, 90%, 61%) */
  --snt-scale-yellow-50:  #443104;
  --snt-scale-yellow-100: #795706;
  --snt-scale-yellow-200: #da9c0b;
  --snt-scale-yellow-500: #f5bf40;
  --snt-scale-yellow-600: #f8d072;
  --snt-scale-yellow-700: #fcebc5;
  --snt-scale-yellow-800: #fefaf0;

  /* Scale / Red — flipped, base hsl(6, 64%, 50%) */
  --snt-scale-red-50:  #471510;
  --snt-scale-red-100: #712219;
  --snt-scale-red-200: #8e2a1f;
  --snt-scale-red-500: #d13d2e;
  --snt-scale-red-600: #ebaaa3;
  --snt-scale-red-700: #f4d1cd;
  --snt-scale-red-800: #fcf3f2;

  /* Scale / Purple — flipped, base hsl(267, 64%, 50%) */
  --snt-scale-purple-50:  #301254;
  --snt-scale-purple-100: #4f1e8a;
  --snt-scale-purple-200: #5d24a3;
  --snt-scale-purple-500: #772ed1;
  --snt-scale-purple-600: #ab7de3;
  --snt-scale-purple-700: #dcc9f3;
  --snt-scale-purple-800: #f7f2fc;

  /* Neutral / Grey — zinc, flipped; 400 = 3.4:1 on the dark surface */
  --snt-neutral-grey-00:  #09090b;
  --snt-neutral-grey-50:  #0e0e10;
  --snt-neutral-grey-100: #18181b;
  --snt-neutral-grey-200: #27272a;
  --snt-neutral-grey-300: #3f3f46;
  --snt-neutral-grey-400: #65656f;
  --snt-neutral-grey-500: #8f8f98;
  --snt-neutral-grey-600: #a1a1aa;
  --snt-neutral-grey-700: #d4d4d8;
  --snt-neutral-grey-800: #f4f4f5;
  --snt-neutral-grey-900: #fafafa;

  /* Neutral / Divider — flipped */
  --snt-neutral-divider-10: rgba(255, 255, 255, 0.08);
  --snt-neutral-divider-20: rgba(255, 255, 255, 0.14);

  /* Surface — flipped */
  --snt-surface-app: #09090b;
  --snt-surface-page: #0c0c0e;
  --snt-surface-row: #09090b;
  --snt-surface-row-hover: #18181b;
  --snt-surface-row-visited: #0e0e10;
  --snt-surface-table-header: #111113;

  /* Feedback — alert changes in dark */
  --snt-feedback-alert: #ff9b90;

  /* Data — flipped */
  --snt-data-1: #0f69aa;
  --snt-data-2: #c1674d;
  --snt-data-3: #2a6898;
  --snt-data-4: #a7adb2;
  --snt-data-5: #9acbe5;
  --snt-data-6: #ffaf97;
  --snt-data-7: #e2f2ff;
  --snt-data-8: #f4f6f8;
  --snt-data-9: #1f5077;
  --snt-data-10: #9b4f39;

  /* Status — error states change in dark */
  --snt-status-cancelled: #ff9b90;
  --snt-status-timeout: #ff9b90;
  --snt-status-error: #ff9b90;
  --snt-status-inaccessible: #ff9b90;
  --snt-status-too-many-inaccessible: #ff9b90;

  /* Text — flipped */
  --snt-text-primary:     #fafafa;
  --snt-text-secondary:   #a1a1aa;
  --snt-text-disabled:    #52525b;
  --snt-text-placeholder: #8f8f98;
  --snt-text-inverse:     #09090b;

  /* Text semantic — dark mode tuned for readability without glare. All AA+ on #0F1010 */
  --snt-text-link:    #a5b4fc; /* indigo 300 — 9.98:1, AAA */
  --snt-text-success: #6fd367; /* balanced green — 10.15:1, AAA (replaces neon lime) */
  --snt-text-warning: #f5bf40; /* vivid amber — 11.26:1, AAA */
  --snt-text-error:   #f87171; /* coral red — 6.89:1, AA (replaces washed pink) */
  --snt-text-info:    #67a9dc; /* medium blue — 7.52:1, AAA (replaces pale wash) */

  /* Button hover-overlay backgrounds — flipped to dark tints so hover doesn't appear as a bright patch on dark page surfaces */
  --snt-btn-primary-50:  #1b1a3f;
  --snt-btn-success-50:  #192900;
  --snt-btn-warning-50:  #443104;
  --snt-btn-error-50:    #471510;
  --snt-btn-neutral-100: #18181b;

  /* Shadow — stronger alpha on dark surfaces */
  --snt-shadow-xs:  0 1px 2px 0 rgba(0, 0, 0, 0.24);
  --snt-shadow-sm:  0 1px 3px 0 rgba(0, 0, 0, 0.32), 0 1px 2px 0 rgba(0, 0, 0, 0.20);
  --snt-shadow-md:  0 4px 6px -1px rgba(0, 0, 0, 0.36), 0 2px 4px -1px rgba(0, 0, 0, 0.24);
  --snt-shadow-lg:  0 10px 15px -3px rgba(0, 0, 0, 0.40), 0 4px 6px -2px rgba(0, 0, 0, 0.28);
  --snt-shadow-xl:  0 20px 25px -5px rgba(0, 0, 0, 0.48), 0 10px 10px -5px rgba(0, 0, 0, 0.32);
  --snt-shadow-2xl: 0 25px 50px -12px rgba(0, 0, 0, 0.60);

  /* shadcn compatibility layer — dark */
  --background: #09090b;
  --foreground: #fafafa;
  --card: #111113;
  --card-foreground: #fafafa;
  --popover: #111113;
  --popover-foreground: #fafafa;
  --primary: #4f46e5;
  --primary-foreground: #ffffff;
  --secondary: #27272a;
  --secondary-foreground: #fafafa;
  --muted: #18181b;
  --muted-foreground: #a1a1aa;
  --accent: #18181b;
  --accent-foreground: #fafafa;
  --destructive: #d13d2e;
  --border: rgba(255, 255, 255, 0.08);
  --input: rgba(255, 255, 255, 0.14);
  --ring: #818cf8;
  --chart-1: #0f69aa;
  --chart-2: #c1674d;
  --chart-3: #2a6898;
  --chart-4: #a7adb2;
  --chart-5: #9acbe5;
}

/* ===================================================================
   SEMANTIC ALIASES — role-based names over the scales above.
   Prefer these in components (and AI-generated code) over scale tokens.
   Re-declared on every theme root so nested [data-snt-theme] subtrees
   resolve the aliases against their own mode.
   =================================================================== */

:root,
.dark,
[data-snt-theme] {
  --snt-text-brand: var(--snt-brand-primary-600);
  --snt-border-default:    var(--snt-neutral-divider-10);  /* Card, table and divider lines */
  --snt-border-strong:     var(--snt-neutral-grey-400);    /* Input and outline-button borders (≥3:1) */
  --snt-border-focus:      var(--snt-brand-primary-600);   /* Focused input border */
  --snt-border-error:      var(--snt-scale-red-600);       /* Invalid input border */
  --snt-bg-subtle:         var(--snt-neutral-grey-100);    /* Hover fills, header bands, neutral chips */
  --snt-bg-brand-subtle:   var(--snt-brand-primary-50);    /* Selected / primary tint */
  --snt-bg-info-subtle:    var(--snt-scale-blue-50);       /* Info tint */
  --snt-bg-success-subtle: var(--snt-scale-green-50);      /* Success tint */
  --snt-bg-warning-subtle: var(--snt-scale-yellow-50);     /* Warning tint */
  --snt-bg-error-subtle:   var(--snt-scale-red-50);        /* Error tint */
  --snt-focus-ring:        var(--snt-brand-primary-500);   /* Keyboard focus ring */
  --snt-focus-ring-error:  var(--snt-scale-red-500);       /* Focus ring on destructive controls */

  /* Type scale — numeric names match the Figma text styles (Text/14/Medium) */
  --snt-font-size-10: 10px;
  --snt-font-size-11: 11px;
  --snt-font-size-12: 12px;
  --snt-font-size-14: 14px;
  --snt-font-size-16: 16px;
  --snt-font-size-18: 18px;
  --snt-font-size-20: 20px;
  --snt-font-size-24: 24px;
  --snt-font-size-32: 32px;
  --snt-font-size-48: 48px;
}

@theme inline {
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);

  /* shadcn compatibility */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
