  .z-sticky   { z-index: var(--snt-z-sticky);   }
  .z-dropdown { z-index: var(--snt-z-dropdown); }
  .z-overlay  { z-index: var(--snt-z-overlay);  }
  .z-sidebar  { z-index: var(--snt-z-sidebar);  }
  .z-modal    { z-index: var(--snt-z-modal);    }
  .z-toast    { z-index: var(--snt-z-toast);    }

  /* Motion — semantic duration / easing utilities */
  .duration-instant   { transition-duration: var(--snt-motion-duration-instant);   }
  .duration-snap      { transition-duration: var(--snt-motion-duration-snap);      }
  .duration-default   { transition-duration: var(--snt-motion-duration-default);   }
  .duration-emphasis  { transition-duration: var(--snt-motion-duration-emphasis);  }
  .duration-spatial   { transition-duration: var(--snt-motion-duration-spatial);   }
}

@keyframes toast-timer {
  from { width: 100%; }
  to   { width: 0%;   }
}

.toast-timer-bar {
  animation: toast-timer 4s linear forwards;
}

@keyframes snt-pulse-dot {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

.snt-pulse-dot {
  animation: snt-pulse-dot 2s infinite;
}

@keyframes snt-gauge-draw {
  to {
    stroke-dashoffset: 0;
  }
}

.snt-scrollbar-hide {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.snt-scrollbar-hide::-webkit-scrollbar {
  display: none;
}

/* Respect the OS "reduce motion" setting (WCAG 2.3.3). */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
